#!/usr/bin/env python3
from __future__ import annotations

import base64
import hashlib
import json
import py_compile
import shutil
from datetime import datetime
from pathlib import Path

PATCH_NAME = "bc_dpg_current_model_stage2"
PATCH_VERSION = "2026.07.21-v2"
FILES = json.loads('{"scripts/run_bc_dpg_v31_shift_reg_sweep.py":{"b64":"","sha256":"ae3534a68c6c1dcd39f9d652adb037d6ef7ea8474bf10cac3dff94110fed089c","mode":"755"},"scripts/select_bc_dpg_v31_shift_reg.py":{"b64":"","sha256":"006b735c3694c208ec4372c47fafeb25a4e05d14a05e5b163ade60977ab63e92","mode":"755"},"scripts/build_bc_dpg_v3_deployment_comparison.py":{"b64":"","sha256":"167e8260fc5e7ee295352216cd6c58ef7af7b37218893bd2fefed94cd149eb81","mode":"755"},"scripts/freeze_bc_dpg_v3_evidence.py":{"b64":"","sha256":"eec247fbc10e8769229de5371a74673744b1a5b3a30d64bbcc9f32a96fb2e882","mode":"755"}}')


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def main() -> None:
    project_root = Path(__file__).resolve().parent
    required = [
        project_root / "training" / "train_target_protected_scan_calibrator_ablation.py",
        project_root / "models" / "target_protected_scan_calibrator.py",
        project_root / "results" / "data_audit" / "dataset_v4_multifold",
    ]
    missing = [str(path.relative_to(project_root)) for path in required if not path.exists()]
    if missing:
        print("[错误] 请把本安装器直接放在 balloon_radar_project 项目根目录。")
        print("缺少以下必要路径：")
        for item in missing:
            print(f"  - {item}")
        raise SystemExit(2)

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_root = project_root / "backups" / f"{PATCH_NAME}_{timestamp}"
    installed = []

    for relative, meta in FILES.items():
        target = project_root / relative
        data = base64.b64decode(meta["b64"])
        actual = sha256_bytes(data)
        if actual != meta["sha256"]:
            raise RuntimeError(f"内置文件哈希异常：{relative}")

        if target.exists():
            backup = backup_root / relative
            backup.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target, backup)

        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(data)
        target.chmod(int(meta["mode"], 8))
        py_compile.compile(str(target), doraise=True)
        if sha256_bytes(target.read_bytes()) != meta["sha256"]:
            raise RuntimeError(f"安装后哈希校验失败：{relative}")
        installed.append({
            "relative_path": relative,
            "sha256": meta["sha256"],
        })

    record_dir = project_root / "results" / "patch_records"
    record_dir.mkdir(parents=True, exist_ok=True)
    record_path = record_dir / f"{PATCH_NAME}_{timestamp}.json"
    record_path.write_text(
        json.dumps(
            {
                "patch_name": PATCH_NAME,
                "patch_version": PATCH_VERSION,
                "installed_at": datetime.now().isoformat(timespec="seconds"),
                "backup_root": str(backup_root) if backup_root.exists() else None,
                "files": installed,
            },
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    print("=" * 82)
    print("BC-DPG-FCN 当前模型 Stage 2 安装完成")
    print(f"版本：{PATCH_VERSION}")
    for item in installed:
        print(f"  + {item['relative_path']}")
    if backup_root.exists():
        print(f"原文件备份：{backup_root.relative_to(project_root)}")
    print(f"安装记录：{record_path.relative_to(project_root)}")
    print("")
    print("下一步先运行：")
    print("python scripts/build_bc_dpg_v3_deployment_comparison.py --require-all")
    print("python scripts/freeze_bc_dpg_v3_evidence.py")
    print(
        "python scripts/run_bc_dpg_v31_shift_reg_sweep.py "
        "--folds 1 4 --regularizations 0.01 0.005 0.0025 0.001 0 --smoke"
    )
    print("=" * 82)


if __name__ == "__main__":
    main()
